      {q:"¿Por qué las intraorales requieren aperturas tan cerradas (f/22-f/32)?", ops:["Para que entre más luz","Para asegurar nitidez desde la línea media hasta los molares","Para reducir el ISO","Para acelerar el obturador"], correcta:1, explicacion:"Se necesita gran profundidad de campo para que todo el arco quede nítido, de la línea media a los molares."},
      {q:"¿Cuál es la diferencia de objetivo entre registro estandarizado y fotografía artística?", ops:["No hay diferencia","Estandarizado: diagnóstico y médico-legal. Artística: detalle, textura y marketing","Estandarizado: marketing. Artística: diagnóstico","Solo cambia la cámara"], correcta:1, explicacion:"El registro estandarizado es diagnóstico y de protección médico-legal; la artística busca detalle, texturas y marketing."},
      {q:"En el frontal en reposo, ¿qué debe verse en cuanto a los labios?", ops:["Sellado forzado","Labios en posición de descanso sin forzar el sellado","Labios en sonrisa amplia","Labios retraídos con retractores"], correcta:1, explicacion:"Los labios deben estar en descanso, sin forzar el sellado — así se valora la competencia labial real."},
      {q:"¿Para qué sirve principalmente el frontal en reposo?", ops:["Determinar la clasificación de Angle","Valorar competencia labial, asimetrías y exposición de incisivos en reposo","Analizar la curva de Spee","Medir el overjet"], correcta:1, explicacion:"Valora asimetrías transversales, competencia labial, hipertonía del mentoniano y exposición en mm de incisivos superiores en reposo."},
      {q:"¿Qué se analiza en el frontal en sonrisa?", ops:["Línea de sonrisa, corredor bucal y líneas medias","La relación molar","La forma de la arcada","El ángulo nasolabial"], correcta:0, explicacion:"Analiza línea de sonrisa (alta, media, baja), corredor bucal, consonancia con el labio inferior y desviación de líneas medias."},
      {q:"En la toma de perfil, ¿qué indica que el perfil es estricto?", ops:["Que se ven ambas orejas","Que NO se ven las pestañas del ojo contrario","Que se ve toda la frente","Que el paciente sonríe"], correcta:1, explicacion:"En perfil estricto no se deben ver las pestañas del ojo izquierdo (al fotografiar el derecho)."},
      {q:"¿Qué extensión anatómica debe abarcar la fotografía de perfil?", ops:["De la nariz al mentón","De la glabela al cartílago tiroides","Solo el tercio inferior","De la frente a los hombros"], correcta:1, explicacion:"El perfil comprende desde la glabela hasta el cartílago tiroides en el cuello."},
      {q:"¿Qué retractor se usa en la toma frontal en oclusión?", ops:["Retractor en C","Retractor en V","Espejo oclusal","Contrastador"], correcta:0, explicacion:"Los retractores en 'C' deben despejar completamente comisuras y frenillos laterales."},
      {q:"En las laterales, ¿cómo deben manejarse los retractores?", ops:["Ambos traccionan por igual","El del lado a fotografiar tracciona fuerte; el opuesto solo se sostiene","Solo se usa uno","No se usan retractores"], correcta:1, explicacion:"El retractor en 'V' del lado a fotografiar tracciona fuertemente hacia atrás; el del lado opuesto solo se sostiene sin tensión."},
      {q:"¿Dónde se enfoca en la toma lateral?", ops:["En el incisivo central","Sobre la cúspide del canino o el primer premolar","En el último molar","En la encía marginal"], correcta:1, explicacion:"El enfoque va sobre la cúspide del canino o en el primer premolar."},
      {q:"¿Qué permite determinar la fotografía lateral en MIC?", ops:["La forma de la arcada","La Relación Molar y Canina de Angle, el overjet y la Curva de Spee","La línea de sonrisa","La simetría facial"], correcta:1, explicacion:"Determina Relación Molar y Canina de Angle, overjet, Curva de Spee e intercuspidación lateral."},
      {q:"¿Cómo debe estar el lente respecto al espejo en las oclusales?", ops:["A 45 grados","Perpendicular al reflejo del espejo","Paralelo al piso","Inclinado 30 grados"], correcta:1, explicacion:"El lente debe estar perpendicular al reflejo del espejo, no al espejo físico."},
      {q:"¿Cómo se evita el vaho en el espejo fotográfico?", ops:["Limpiándolo con alcohol","Calentando el espejo o echando aire con la jeringa","Usando más flash","Bajando el ISO"], correcta:1, explicacion:"El vaho se evita calentando el espejo o echando aire con la jeringa triple."},
      {q:"¿Qué elementos NUNCA deben aparecer en una fotografía intraoral terminada?", ops:["Los retractores","Los dedos o guantes del operador","El espejo","Los dientes posteriores"], correcta:1, explicacion:"Los dedos o guantes del operador nunca deben aparecer en la fotografía terminada."},
      {q:"¿Por qué se recomienda un segundo flash esclavo apuntando al fondo?", ops:["Para aumentar el brillo del rostro","Para evitar sombras proyectadas que distorsionen el contorno del rostro","Para reducir el ISO","Para enfocar mejor"], correcta:1, explicacion:"Evita sombras proyectadas que distorsionarían el contorno facial."}
