    avanzado: [
      {q:"Paciente con prótesis reciente que refiere fatiga muscular y dificultad para juntar labios. Conducta:", ops:["Indicar analgésicos y esperar la adaptación neuromuscular", "Evaluar dimensión vertical y espacio libre interoclusal", "Ajustar los contactos posteriores hasta lograr simultaneidad", "Rebasar la prótesis para mejorar su estabilidad y retención"], correcta:1,explicacion:"El cuadro sugiere Clase III iatrogénica. Hay que medir antes de asumir adaptación."},
      {q:"¿Por qué la restauración de la dimensión vertical en Clase V debe ser gradual?", ops:["Para permitir adaptación neuromuscular y articular", "Para evitar la extrusión de los dientes antagonistas", "Para reducir el riesgo de fractura de las restauraciones", "Para dar tiempo a la remodelación del reborde alveolar"], correcta:0,explicacion:"Los cambios bruscos no dan tiempo a la adaptación y pueden desencadenar sintomatología."},
      {q:"¿Por qué la Clase IV de Morris se considera una relación patológica?", ops:["Porque reduce la dimensión vertical de oclusión en el lado cruzado", "Porque impone un esfuerzo muscular continuo y mantiene en alerta al sistema neuromuscular", "Porque provoca la pérdida de los dientes posteriores del lado afectado", "Porque obliga a la mandíbula a un deslizamiento posterior en cada cierre"], correcta:1, explicacion:"La desviación constante al cerrar exige esfuerzo muscular sostenido, con consecuencias en articulaciones y dientes. Martínez Ross, Rehabilitación y reconstrucción oclusal."},
      {q:"La medición del espacio libre interoclusal se realiza:", ops:["Con el paciente en máxima intercuspidación forzada", "Comparando relación céntrica con posición habitual", "En posición de reposo fisiológico comparada con oclusión", "Mediante registro de cera tomado en protrusión"], correcta:2,explicacion:"Es la diferencia entre la dimensión vertical postural y la de oclusión."},
      {q:"Un deslizamiento de céntrica a habitual con componente lateral marcado indica:", ops:["Que el paciente esquiva una interferencia", "Que el registro de céntrica fue tomado con retrusión forzada", "Que existe una asimetría en la inclinación de ambas eminencias", "Que el montaje se realizó sin arco facial de transferencia"], correcta:0,explicacion:"El desvío lateral es evitación de un obstáculo, con costo muscular y articular."},
      {q:"¿Qué limita el uso clínico de esta clasificación?", ops:["Que solo es aplicable en pacientes completamente dentados", "Que no considera la relación anteroposterior de las arcadas", "Que requiere montaje y registros correctos para ser válida", "Que sus categorías se superponen entre sí con frecuencia"], correcta:2,explicacion:"Un registro mal tomado invalida la clasificación por completo."},
      {q:"Según la clasificación de Morris, ¿qué factor agrava y dificulta el tratamiento de cualquier relación patológica?", ops:["La edad avanzada del paciente", "El número de dientes restaurados", "La presencia de factores emocionales", "El antecedente de tratamiento ortodóncico"], correcta:2, explicacion:"La fuente señala que los factores emocionales en el cuadro clínico agravan y dificultan el tratamiento. Martínez Ross, Rehabilitación y reconstrucción oclusal."},
      {q:"En Clase V con pérdida de posteriores, la secuencia lógica incluye:", ops:["Rehabilitar primero el sector anterior por su compromiso estético", "Restablecer soporte posterior y dimensión vertical", "Ferulizar los anteriores antes de restaurar los posteriores", "Realizar ajuste oclusal previo a cualquier rehabilitación"], correcta:1,explicacion:"Sin soporte posterior restablecido, los anteriores seguirán sobrecargados."},
      {q:"La férula puede usarse en estas clases como:", ops:["Tratamiento definitivo cuando la rehabilitación no es viable", "Método para acelerar la adaptación muscular al cambio", "Prueba diagnóstica de la nueva posición antes de rehabilitar", "Elemento de retención tras el ajuste oclusal realizado"], correcta:2,explicacion:"Permite ensayar la posición de forma reversible antes de comprometerse."},
      {q:"Al cerrar, la mandíbula se desvía hacia adelante y a un lado por un contacto en un premolar, sin que exista oclusión cruzada. ¿Qué clase es y qué la distingue de la Clase IV?", ops:["Clase IV: toda desviación lateral corresponde a esta clase", "Clase I: la causa es una prematuridad, no una oclusión cruzada", "Clase II: el contacto obliga a un deslizamiento posterior", "Clase III: el contacto indica una restauración en supraoclusión"], correcta:1, explicacion:"Ambas terminan en lateroprotrusión, pero la Clase I la produce una prematuridad y la Clase IV una oclusión cruzada posterior. Martínez Ross, Rehabilitación y reconstrucción oclusal."},
      {q:"¿Qué hace más confiable el diagnóstico de clase?", ops:["Repetir el registro y verificar reproducibilidad", "Complementar con radiografía panorámica de ambas articulaciones", "Utilizar articulador totalmente ajustable en lugar de semiajustable", "Tomar el registro con el paciente en decúbito supino"], correcta:0,explicacion:"Un registro no reproducible no es válido. La reproducibilidad es el control de calidad."},
      {q:"En un paciente con Clase III iatrogénica, la primera medida es:", ops:["Colocar férula de estabilización mientras cede la sintomatología", "Rehabilitar el arco antagonista para compensar la altura", "Identificar y corregir la restauración responsable", "Prescribir relajantes musculares y control en dos semanas"], correcta:2,explicacion:"Si la causa es una restauración alta, corregirla es la intervención directa."},
      {q:"La relación entre estas clases y los trastornos temporomandibulares es:", ops:["Un factor contribuyente dentro de un modelo multifactorial", "Una relación causal directa en las Clases II y V", "Una asociación demostrada solo en pacientes bruxistas", "Una consecuencia del trastorno articular, no su causa"], correcta:0,explicacion:"Contribuyen, pero no explican por sí solas la aparición del trastorno."},
      {q:"Al comparar montajes en céntrica y habitual, lo que se documenta es:", ops:["La inclinación de la trayectoria condílea de cada lado", "El grado de desoclusión posterior en los movimientos excéntricos", "Magnitud y dirección del deslizamiento y primer contacto", "La diferencia de dimensión vertical entre ambas posiciones"], correcta:2,explicacion:"Esos tres datos son el hallazgo diagnóstico del ejercicio."},
      {q:"El principal error que invalida esta clasificación en la práctica es:", ops:["Utilizar cera rosa en lugar de silicona para el registro", "Montar el modelo inferior antes que el superior", "Omitir el arco facial y usar valores promedio", "Registrar sin desprogramar al paciente"], correcta:3,explicacion:"Sin desprogramación se registra la posición habitual creyendo que es céntrica, y todo el análisis falla."},
      {q:"¿Cuál es la diferencia fundamental entre la clasificación de Angle y la de Morris?", ops:["Angle es funcional y Morris es morfológica","Angle describe la relación molar anteroposterior; Morris describe la dirección de la desviación mandibular al cerrar","Ambas describen lo mismo con distintos nombres","Angle solo se usa en ortodoncia y Morris solo en prótesis"], correcta:1, explicacion:"Angle (Clases I-II-III) es morfológica y se basa en los primeros molares. Morris (Clases I-V) es funcional y describe hacia dónde desvían los obstáculos a la mandíbula. Comparten números pero no son lo mismo. Okeson no utiliza la clasificación de Morris."},
      {q:"Un alumno dice: 'el paciente es Clase IV'. ¿Qué debes preguntar de inmediato?", ops:["¿De Angle o de Morris?","¿Es unilateral o bilateral?","¿Tiene dolor articular?","¿Qué tipo de férula necesita?"], correcta:0, explicacion:"Siempre hay que especificar la clasificación. Clase IV de Morris es latero-protrusiva; Angle solo llega a Clase III. La ambigüedad es un error frecuente en exámenes y en clínica."},
      {q:"En un examen te preguntan la 'Clase IV' de un paciente. ¿Qué debes aclarar antes de responder?", ops:["Si es unilateral o bilateral","Si es de Angle o de Morris (Angle solo llega a III)","Si tiene dolor o solo ruido","Si necesita férula o ajuste"], correcta:1, explicacion:"Angle: I, II, III. Morris: I a V. Clase IV solo existe en Morris (latero-protrusiva). No aclararlo es un error clásico."},
      {q:"Un paciente Clase I de Angle presenta interferencia de balance y dolor muscular. Según Okeson, ¿qué es más relevante para el tratamiento?", ops:["Corregir la Clase I a una relación 'más ideal'","La presencia de daño (dolor) y la interferencia lesiva, no la clase de Angle","Indicar cirugía ortognática","Ignorar la interferencia porque es Clase I"], correcta:1, explicacion:"La clase de Angle no define el tratamiento del TTM. Importan el daño, la adaptación y los criterios de oclusión funcional óptima."},
]
